<!DOCTYPE html>
<html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Password Baru — SIMKAP</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;font-family:Arial,sans-serif;background:#eff6ff;color:#0f172a}.card{width:min(100%,440px);padding:32px;background:#fff;border-radius:16px;box-shadow:0 12px 35px #94a3b844}h1{font-size:22px;margin:0 0 8px}p{color:#475569;font-size:14px;line-height:1.55}.group{margin:18px 0}label{display:block;font-size:13px;font-weight:bold;margin-bottom:6px}input{width:100%;padding:11px 12px;border:1px solid #cbd5e1;border-radius:8px;font-size:14px}button{width:100%;padding:12px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-weight:bold;cursor:pointer}.error{margin-top:7px;color:#b91c1c;font-size:12px}</style></head><body><main class="card"><h1>Buat Password Baru</h1><p>Masukkan password baru untuk akun Anda.</p><form method="POST" action="{{ route('password.update') }}">@csrf<input type="hidden" name="token" value="{{ $token }}"><div class="group"><label for="email">Email akun</label><input id="email" type="email" name="email" value="{{ old('email', $email) }}" required autocomplete="email">@error('email')<div class="error">{{ $message }}</div>@enderror</div><div class="group"><label for="password">Password baru</label><input id="password" type="password" name="password" minlength="8" required autofocus autocomplete="new-password">@error('password')<div class="error">{{ $message }}</div>@enderror</div><div class="group"><label for="password_confirmation">Konfirmasi password baru</label><input id="password_confirmation" type="password" name="password_confirmation" minlength="8" required autocomplete="new-password"></div><button type="submit">Simpan Password Baru</button></form></main></body></html>
